// TestShadow_TurnEndPushesWhenFlagged tests the full lifecycle:
// 1. Agent starts turn (ACTIVE)
// 2. Agent makes changes and commits
// 3. PrePush would set PushedDuringTurnRemote (we simulate this)
// 4. Agent stops → HandleTurnEnd finalizes + attempts push
// 5. PushedDuringTurnRemote is cleared
func TestShadow_TurnEndPushesWhenFlagged(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t)
	sess := env.NewSession()

	// 1. Start session
	if err := env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(
		sess.ID, "Build a feature", sess.TranscriptPath,
	); err != nil {
		t.Fatalf("user-prompt-submit failed: %v", err)
	}

	// 2. Create file and transcript, then commit
	env.WriteFile("feature.go", "package main\n\nfunc Feature() {}\n")
	sess.CreateTranscript("Build a feature", []FileChange{
		{Path: "feature.go", Content: "package main\n\nfunc Feature() {}\n"},
	})

	env.GitAdd("feature.go")
	env.GitCommit("Add feature")
	env.SimulatePostCommit()

	// 3. Simulate PrePush setting the flag (no actual remote in test)
	state, err := env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state.Phase != session.PhaseActive {
		t.Fatalf("Expected ACTIVE phase, got %s", state.Phase)
	}
	if len(state.TurnCheckpointIDs) == 0 {
		t.Fatal("Expected TurnCheckpointIDs to be populated after mid-turn commit")
	}

	state.PushedDuringTurnRemote = "origin"
	env.SaveSessionState(state)

	// 4. Agent continues, updates transcript
	sess.AppendTranscript("Build a feature", []FileChange{
		{Path: "feature.go", Content: "package main\n\nfunc Feature() { /* updated */ }\n"},
	})

	// 5. Agent stops
	env.SimulateStop(sess.ID, sess.TranscriptPath)

	// 6. Verify flag was cleared
	state, err = env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state.PushedDuringTurnRemote != "" {
		t.Errorf("PushedDuringTurnRemote should be cleared after stop, got %q",
			state.PushedDuringTurnRemote)
	}
	if len(state.TurnCheckpointIDs) != 0 {
		t.Errorf("TurnCheckpointIDs should be cleared after stop, got %v",
			state.TurnCheckpointIDs)
	}
}

