 904→// gitCommitWithShadowHooks is the shared implementation for committing with shadow hooks.
 905→// When simulateTTY is true, sets ENTIRE_TEST_TTY=1 to simulate a human at the terminal.
 906→// When false, filters it out to simulate an agent subprocess (no controlling terminal).
 907→func (env *TestEnv) gitCommitWithShadowHooks(message string, simulateTTY bool, files ...string) {
 908→	env.T.Helper()
 909→
 910→	// Stage files using go-git
 911→	for _, file := range files {
 912→		env.GitAdd(file)
 913→	}
 914→
 915→	// Create a temp file for the commit message (prepare-commit-msg hook modifies this)
 916→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
 917→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
 918→		env.T.Fatalf("failed to write commit message file: %v", err)
 919→	}
 920→
 921→	// Run prepare-commit-msg hook using the shared binary.
 922→	// Pass source="message" to match real `git commit -m` behavior.
 923→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile, "message")
 924→	prepCmd.Dir = env.RepoDir
 925→	if simulateTTY {
 926→		// Simulate human at terminal: ENTIRE_TEST_TTY=1 makes hasTTY() return true
 927→		// and askConfirmTTY() return defaultYes without reading from /dev/tty.
 928→		prepCmd.Env = append(testutil.GitIsolatedEnv(), "ENTIRE_TEST_TTY=1")
 929→	} else {
 930→		// Simulate agent: ENTIRE_TEST_TTY=0 makes hasTTY() return false,
 931→		// triggering the fast path that adds trailers for ACTIVE sessions.
 932→		prepCmd.Env = append(testutil.GitIsolatedEnv(), "ENTIRE_TEST_TTY=0")
 933→	}
 934→	if output, err := prepCmd.CombinedOutput(); err != nil {
 935→		env.T.Logf("prepare-commit-msg output: %s", output)
 936→		// Don't fail - hook may silently succeed
 937→	}
 938→
 939→	// Read the modified message
 940→	modifiedMsg, err := os.ReadFile(msgFile)
 941→	if err != nil {
 942→		env.T.Fatalf("failed to read modified commit message: %v", err)
 943→	}
 944→
 945→	// Create the commit using go-git with the modified message
 946→	repo, err := git.PlainOpen(env.RepoDir)
 947→	if err != nil {
 948→		env.T.Fatalf("failed to open git repo: %v", err)
 949→	}
 950→
 951→	worktree, err := repo.Worktree()
 952→	if err != nil {
 953→		env.T.Fatalf("failed to get worktree: %v", err)
 954→	}
 955→
 956→	_, err = worktree.Commit(string(modifiedMsg), &git.CommitOptions{
 957→		Author: &object.Signature{
 958→			Name:  "Test User",
 959→			Email: "test@example.com",
 960→			When:  time.Now(),
 961→		},
 962→	})
 963→	if err != nil {
 964→		env.T.Fatalf("failed to commit: %v", err)
 965→	}
 966→
 967→	// Run post-commit hook using the shared binary
 968→	// This triggers condensation if the commit has an Entire-Checkpoint trailer
 969→	postCmd := exec.Command(getTestBinary(), "hooks", "git", "post-commit")
 970→	postCmd.Dir = env.RepoDir
 971→	if output, err := postCmd.CombinedOutput(); err != nil {
 972→		env.T.Logf("post-commit output: %s", output)
 973→		// Don't fail - hook may silently succeed
 974→	}
 975→}
