1040→// GitCommitWithTrailerRemoved stages and commits files, simulating what happens when
1041→// a user removes the Entire-Checkpoint trailer during commit message editing.
1042→// This tests the opt-out behavior where removing the trailer skips condensation.
1043→func (env *TestEnv) GitCommitWithTrailerRemoved(message string, files ...string) {
1044→	env.T.Helper()
1045→
1046→	// Stage files using go-git
1047→	for _, file := range files {
1048→		env.GitAdd(file)
1049→	}
1050→
1051→	// Create a temp file for the commit message (prepare-commit-msg hook modifies this)
1052→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
1053→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
1054→		env.T.Fatalf("failed to write commit message file: %v", err)
1055→	}
1056→
1057→	// Run prepare-commit-msg hook using the shared binary.
1058→	// Set ENTIRE_TEST_TTY=1 to simulate human (this tests the editor flow where
1059→	// the user removes the trailer before committing).
1060→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile)
1061→	prepCmd.Dir = env.RepoDir
1062→	prepCmd.Env = append(testutil.GitIsolatedEnv(), "ENTIRE_TEST_TTY=1")
1063→	if output, err := prepCmd.CombinedOutput(); err != nil {
1064→		env.T.Logf("prepare-commit-msg output: %s", output)
1065→	}
1066→
1067→	// Read the modified message (with trailer added by hook)
1068→	modifiedMsg, err := os.ReadFile(msgFile)
1069→	if err != nil {
1070→		env.T.Fatalf("failed to read modified commit message: %v", err)
1071→	}
1072→
1073→	// REMOVE the Entire-Checkpoint trailer (simulating user editing the message)
1074→	lines := strings.Split(string(modifiedMsg), "\n")
1075→	var cleanedLines []string
