	require.NoError(t, err)

	headTree, err := commit.Tree()
	require.NoError(t, err)
	var parentTree *object.Tree
	if commit.NumParents() > 0 {
		parent, pErr := commit.Parent(0)
		require.NoError(t, pErr)
